roll:
function rollRoomMods(r) {
  const o = { obj: null, lay: null }; if (r < 2) return o;
  if (crand() < .7) { const ks = r >= 3 ? ['siege', 'hunt', 'lantern', 'gauntlet'] : ['siege', 'hunt', 'lantern']; o.obj = ks[Math.floor(crand() * ks.length)]; }
  if (crand() < .65) { const ls = ['pillars', 'chasm', 'collapse']; o.lay = ls[Math.floor(crand() * ls.length)]; if (o.obj === 'lantern' && o.lay === 'collapse') o.lay = 'pillars'; }
  return o;
}

setup:
function setupRoomMods() {
  const m = G.nextMods || { obj: null, lay: null }; G.nextMods = null; G.obj = null; G.lay = m.lay && !G.isBoss ? makeLayout(m.lay) : null;
  if (!m.obj || G.isBoss) return;
  const k = m.obj;
  if (k === 'siege') { G.obj = { k, t: 25, spawnT: 1 }; G.waves = []; }
  else if (k === 'hunt') { G.obj = { k, t: 20, done: false }; G.waves = G.waves.slice(0, 2); }
  else if (k === 'lantern') G.obj = { k, hp: 150 + G.room * 6, max: 150 + G.room * 6, x: 0, y: -30 };
  else if (k === 'gauntlet') { G.obj = { k, a: crand() * TAU, arms: G.room >= 15 ? 3 : 2, trapT: 2.5 }; G.waves = G.waves.map(w => w.slice(0, Math.ceil(w.length * .7))); }
  setTimeout(() => { if (G && G.obj) { banner(OBJN[G.obj.k]); sfx('shimmer'); if (G.obj.k === 'gauntlet') sfx('beam'); } }, 1500);
}

update:
function updObjective(dt) {
  const o = G.obj, p = G.p; if (!o || G.phase !== 'fight') return;
  if (o.k === 'siege') {
    o.t -= dt; o.spawnT -= dt; const alive = G.enemies.filter(e => !e.dead).length;
    if (o.t > 0 && o.spawnT <= 0 && alive < 16) {
      const pool = roomWaves(G.room).flat(); const n = 2 + (Math.random() < .5);
      for (let i = 0; i < n; i++) { let x, y, k = 0; do { const a = rand(0, TAU); x = Math.cos(a) * (ARENA - 90); y = Math.sin(a) * (ARENA - 90); } while ((blocked(x, y, 30) || hyp(x - p.x, y - p.y) < 260) && ++k < 12);
        G.spawns.push({ x, y, type: pool[Math.floor(Math.random() * pool.length)], t: rand(.4, .7), elite: false }); }
      o.spawnT = Math.max(.9, 1.9 - (25 - o.t) * .04);
    }
    if (o.t <= 0 && !o.over) { o.over = true; G.spawns.length = 0; for (const e of G.enemies) if (!e.dead && !e.boss) { e.hp = 0; killEnemy(e, 'launch'); } banner('Dayandın!'); G.shards += 8; addFervor(30); }
  }
  else if (o.k === 'hunt') {
    o.t -= dt;
    if (!o.spawned && G.time > 1.2) { o.spawned = true; const a = rand(0, TAU), e = makeEnemyFull('ghoul', Math.cos(a) * 300, Math.sin(a) * 300); e.runner = true; e.spd *= 1.75; e.hp = e.maxHp = e.maxHp * 2.2; e.dmg = 0; G.enemies.push(e); o.e = e; burst(e.x, e.y, '#ffd27a', 16, 240, .5); }
    if (o.e && !o.done && !o.e.dead && o.t <= 0) { o.done = true; o.e.dead = true; burst(o.e.x, o.e.y, '#ffd27a', 20, 300, .6); banner('Kaçtı'); }
  }
  else if (o.k === 'lantern' && o.hp > 0) {
    for (const e of G.enemies) if (!e.dead && !e.dying && e.lt && hyp(e.x - o.x, e.y - o.y) < e.r + 30) { o.hp -= e.dmg * 1.1 * dt; o.hitT = .15; }
    o.hitT = (o.hitT || 0) - dt;
    if (o.hp <= 0) { o.hp = 0; banner('Fener söndü'); starBoom(o.x, o.y, 60); sfx('boom', o.x); for (const e of G.enemies) e.lt = false; }
  }
  else if (o.k === 'gauntlet') {
    o.a += (.4 + G.room * .005) * dt; o.trapT -= dt;
    const hopping = p.state === 'hop' || p.state === 'fling' || p.state === 'rise';
    if (!hopping && !invuln()) for (let k = 0; k < o.arms; k++) { const a = o.a + k * TAU / o.arms; if (segDist(Math.cos(a) * 70, Math.sin(a) * 70, Math.cos(a) * ARENA, Math.sin(a) * ARENA, p.x, p.y) < 16) { hurt(6 + G.room * .35, 'Işık kolu'); const side = Math.sign(Math.cos(a) * p.y - Math.sin(a) * p.x) || 1; p.x += -Math.sin(a) * side * 40; p.y += Math.cos(a) * side * 40; break; } }
    if (o.trapT <= 0) { o.trapT = 2.4; const a = rand(0, TAU), rr = rand(0, 90); G.erupts.push({ x: p.x + Math.cos(a) * rr, y: p.y + Math.sin(a) * rr, r: 52, t: .95, max: .95, dmg: 8 + G.room * .5, trap: true }); }
  }
}
